        @NotBlank(message = "commandKey 不能为空") String commandKey,
        @NotBlank(message = "disposition 不能为空") String disposition,
        String reason,
        String reworkBatchKey,
        String reworkBatchNo
) {
}

package com.example.starter.batch.dto;

