                BatchStatus snapshot = a.seq() == 1
                        ? BatchStatus.RELEASE_REVIEW
                        : BatchStatus.RELEASED;
                return new ApprovalResponse(a.batchKey(), a.actorId(), ApprovalRole.valueOf(a.role()),
                        a.seq(), snapshot, Instant.parse(a.createdAt()));
