            .map(r -> new RecallResponse(r.batchKey(), r.actorId(), r.reason(),
                    BatchStatus.RECALLED, Instant.parse(r.createdAt())))
            .orElse(null);
    List<ExcursionResponse> excursions = repo.findExcursions(batchKey).stream()
            .map(this::toExcursionResponse)
            .toList();

